import{_ as c,l as s,o as a,c as l,v as o,p as i,x as t,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"execve","description":"","frontmatter":{"title":"execve","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/execve.md","filePath":"cs/execve.md","lastUpdated":1789023840000}'),h={name:"cs/execve.md"};function x(m,e,E,_,f,u){const r=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="execve" tabindex="-1">execve <a class="header-anchor" href="#execve" aria-label="Permalink to &quot;execve&quot;">​</a></h1><div class="epigraph"><p>exec 用一个新程序覆盖当前进程的用户地址空间，PID 不变；成功则不返回，失败才回到旧映像。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Silberschatz et al. 整理</footer></div><p><a href="/cs/fork">上一课</a>造出子进程，但子仍跑同一段代码。shell 要子去执行用户键入的命令，必须<strong>换掉用户页、入口 PC 与栈上的 argv/envp</strong>，同时保留 PCB 的身份（PID、打开的文件除非 close-on-exec）。缺口是 <code>execve</code>，不是再复制一份 PCB。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若 fork 已经复制了父的堆栈，子直接跳进新程序会带着旧映射。exec：打开可执行文件（权限与解释器头是文件课），建立新的用户地址空间，把参数拷进新栈，把 trapframe 的 PC 指向入口，丢掉旧用户页。<a href="/cs/load-dynlink">加载与动态链接</a> 的用户态加载器可以在 exec 后作为解释器再跑；本课只钉内核把映像换成「新程序已就绪」。</p><p><span class="marginnote">成功的 exec 在用户看来是：调用没有返回。失败（找不到文件、不是可执行）返回错误，旧地址空间原封不动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>校验路径与权限 → 读入文件头 → 分配新 <code>mm</code>、装入段或设立后课的按需调页 → 安装新用户栈（argc/argv/envp）→ 关闭 close-on-exec 描述符 → 重置信号处理为默认（捕获函数地址已无意义）→ 从新 trapframe 返回用户。动态链接器作为程序解释器时，内核先把解释器装入，用户入口是 ld.so。</p>',8)),(a(),i(p,null,{default:t(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E7%94%A8%E6%88%B7%E6%98%A0%E5%83%8F%22%5D%20--%3E%20EXEC%5B%22execve%22%5D%0A%20%20EXEC%20--%3E%20NEW%5B%22%E6%96%B0%E9%A1%B5%E8%A1%A8%E4%B8%8E%E5%85%A5%E5%8F%A3%22%5D%0A%20%20EXEC%20--%3E%20FAIL%5B%22%E5%A4%B1%E8%B4%A5%3A%20%E4%BB%8D%E5%9C%A8%E6%97%A7%E6%98%A0%E5%83%8F%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>线程：POSIX 规定 exec 后只留调用线程；其余线程结束。本课点名，不写实现。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>exec 与 fork 合在一起才是「创建运行新程序」：身份来自 fork，内容来自 exec。PID 不变，于是父的 <code>wait</code> 仍找得到这个孩子。文件系统的 shebang 把脚本变成「解释器 + 脚本路径」，仍是一次 exec 语义。</p><p>不把新程序写成「在旧堆上覆盖字节」：页表根换成新的，旧页引用计数下降，为零则释放。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 ELF 节表当正文，不讨论 setuid 的全部安全后效——那是安全课。也不把 <code>posix_spawn</code> 优化路径当成另一种操作系统。按需调页如何让 exec 不立刻读入全部段，是虚存课。</p><p>后课默认：进程可以换成新程序且 PID 不变。子结束时父如何收取退出码、为何会留下僵尸，下一课讲 <code>wait</code>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>execve 覆盖用户映像，PID 与多数打开文件保留。</li><li>成功不返回；失败才回到旧代码。</li><li>父收取退出状态是下一课。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const P=c(h,[["render",x]]);export{v as __pageData,P as default};
